file.content:
### Task 9: Oturum context'i ve kok yonlendirme

**Files:**
- Create: `mobil/lib/oturum.tsx`
- Test: `mobil/lib/oturum.test.tsx`
- Modify: `mobil/app/_layout.tsx`

**Interfaces:**
- Consumes: `supabase` (Task 4).
- Produces: `OturumSaglayici` (React context provider), `useOturum(): { oturum:
  Session | null, yukleniyor: boolean }` — Task 12 ve kok layout bunu kullanir.

- [ ] **Step 1: Basarisiz testi yaz**

`mobil/lib/oturum.test.tsx`:

```tsx
import { render, screen, waitFor } from '@testing-library/react-native'
import { Text } from 'react-native'
import { OturumSaglayici, useOturum } from './oturum'
import { supabase } from './supabase'

jest.mock('./supabase', () => ({
  supabase: {
    auth: {
      getSession: jest.fn(),
      onAuthStateChange: jest.fn(() => ({ data: { subscription: { unsubscribe: jest.fn() } } })),
    },
  },
}))

function TestBileseni() {
  const { oturum, yukleniyor } = useOturum()
  if (yukleniyor) return <Text>yukleniyor</Text>
  return <Text>{oturum ? 'oturum-var' : 'oturum-yok'}</Text>
}

describe('OturumSaglayici', () => {
  it('baslangicta mevcut oturumu okur', async () => {
    ;(supabase.auth.getSession as jest.Mock).mockResolvedValue({
      data: { session: { user: { id: '1' } } },
    })
    render(
      <OturumSaglayici>
        <TestBileseni />
      </OturumSaglayici>
    )
    await waitFor(() => {
      expect(screen.getByText('oturum-var')).toBeTruthy()
    })
  })

  it('oturum yoksa oturum-yok gosterir', async () => {
    ;(supabase.auth.getSession as jest.Mock).mockResolvedValue({ data: { session: null } })
    render(
      <OturumSaglayici>
        <TestBileseni />
      </OturumSaglayici>
    )
    await waitFor(() => {
