  useRouter: () => ({ push: mockRouterPush }),
}))

describe('KayitEkrani', () => {
  it('gecersiz telefon numarasinda hata gosterir', async () => {
    render(<KayitEkrani />)
    fireEvent.changeText(screen.getByPlaceholderText('05XX XXX XX XX'), '123')
    fireEvent.changeText(screen.getByPlaceholderText('Sifre'), 'sifre1234')
    fireEvent.press(screen.getByText('Kayit ol'))
    await waitFor(() => {
      expect(screen.getByText('Gecerli bir telefon numarasi gir')).toBeTruthy()
    })
    expect(supabase.auth.signUp).not.toHaveBeenCalled()
  })

  it('gecerli bilgilerle signUp cagirir ve dogrulama ekranina yonlendirir', async () => {
    ;(supabase.auth.signUp as jest.Mock).mockResolvedValue({ data: {}, error: null })
    render(<KayitEkrani />)
    fireEvent.changeText(screen.getByPlaceholderText('05XX XXX XX XX'), '5551234567')
