### Task 9: Oturum context'i ve kok yonlendirme

**Files:**
- Create: `mobil/lib/oturum.tsx`
- Test: `mobil/lib/oturum.test.tsx`
- Modify: `mobil/app/_layout.tsx`

**Interfaces:**
- Consumes: `supabase` (Task 4), `public.profiller` tablosu (Task 3).
- Produces: `OturumSaglayici` (React context provider), `useOturum(): { oturum:
  Session | null, profilVarMi: boolean | null, yukleniyor: boolean }` — Task 12
  ve kok layout bunu kullanir. `profilVarMi`, oturum yoksa `null`; oturum varsa
  `profiller` tablosunda satir olup olmadigini yansitir. Bu, oturumu acik ama
  profilini yarim birakan bir kullanicinin uygulama yeniden acildiginda
  dogrudan ana ekrana degil, `/profil-olustur`'a yonlendirilmesini saglar.

- [ ] **Step 1: Basarisiz testi yaz**

`mobil/lib/oturum.test.tsx`:

```tsx
import { render, screen, waitFor } from '@testing-library/react-native'
import { Text } from 'react-native'
import { OturumSaglayici, useOturum } from './oturum'
import { supabase } from './supabase'

jest.mock('./supabase', () => ({
  supabase: {
    auth: {
      getSession: jest.fn(),
      onAuthStateChange: jest.fn(() => ({ data: { subscription: { unsubscribe: jest.fn() } } })),
    },
    from: jest.fn(),
  },
}))

function TestBileseni() {
  const { oturum, profilVarMi, yukleniyor } = useOturum()
  if (yukleniyor) return <Text>yukleniyor</Text>
  if (!oturum) return <Text>oturum-yok</Text>
  return <Text>{profilVarMi ? 'profil-var' : 'profil-yok'}</Text>
}

describe('OturumSaglayici', () => {
  it('oturum varsa profilin var olup olmadigini kontrol eder', async () => {
    ;(supabase.auth.getSession as jest.Mock).mockResolvedValue({
      data: { session: { user: { id: 'kullanici-1' } } },
    })
    ;(supabase.from as jest.Mock).mockReturnValue({
      select: jest.fn().mockReturnValue({
        eq: jest.fn().mockReturnValue({
          maybeSingle: jest.fn().mockResolvedValue({ data: { id: 'kullanici-1' } }),
        }),
      }),
    })
    render(
      <OturumSaglayici>
        <TestBileseni />
      </OturumSaglayici>
    )
    await waitFor(() => {
      expect(screen.getByText('profil-var')).toBeTruthy()
    })
  })

  it('oturum yoksa profil sorgusu yapmaz', async () => {
    ;(supabase.auth.getSession as jest.Mock).mockResolvedValue({ data: { session: null } })
    render(
      <OturumSaglayici>
        <TestBileseni />
      </OturumSaglayici>
    )
    await waitFor(() => {
      expect(screen.getByText('oturum-yok')).toBeTruthy()
    })
    expect(supabase.from).not.toHaveBeenCalled()
  })
})
